import React from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

export default function Navbar() {
  const { user, logout } = useAuth();
  const location = useLocation();
  const navigate  = useNavigate();

  const active = (path) =>
    location.pathname === path
      ? { background: "var(--tag)", color: "var(--charcoal)" }
      : {};

  const handleLogout = () => { logout(); navigate("/"); };

  return (
    <nav style={{
      position: "sticky", top: 0, zIndex: 100,
      background: "rgba(250,248,244,.95)", backdropFilter: "blur(12px)",
      borderBottom: "1px solid var(--border)", height: "var(--nav-h)",
      display: "flex", alignItems: "center", justifyContent: "space-between",
      padding: "0 40px",
    }}>
      <Link to="/" style={{ fontFamily: "'DM Serif Display',serif", fontSize: 24, color: "var(--charcoal)", textDecoration: "none", letterSpacing: "-.3px" }}>
        Room<span style={{ color: "var(--gold)" }}>ly</span>
      </Link>

      <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
        {[{ to: "/", label: "Home" }, { to: "/explore", label: "Explore" }, { to: "/about", label: "About" }].map(({ to, label }) => (
          <Link key={to} to={to} style={{
            padding: "8px 14px", borderRadius: "var(--r-sm)", textDecoration: "none",
            fontSize: 13, fontWeight: 500, color: "var(--muted)", transition: "all .15s", ...active(to)
          }}>{label}</Link>
        ))}

        {user && (
          <Link to="/dashboard" style={{
            padding: "8px 14px", borderRadius: "var(--r-sm)", textDecoration: "none",
            fontSize: 13, fontWeight: 500, color: "var(--muted)", transition: "all .15s", ...active("/dashboard")
          }}>Dashboard</Link>
        )}

        {user ? (
          <button onClick={handleLogout} className="btn btn-dark" style={{ padding: "9px 22px", fontSize: 13 }}>
            Sign Out
          </button>
        ) : (
          <Link to="/auth">
            <button className="btn btn-dark" style={{ padding: "9px 22px", fontSize: 13 }}>
              Sign In / Register
            </button>
          </Link>
        )}
      </div>
    </nav>
  );
}
